apiRouter.get("/planning/dashboard-metrics", async (_req, res) => {
  try {
    if (isDatabaseUrlConfigured()) {
      const prisma2 = getPrismaClient();
      const [readModel, openOrdersCount, proposals] = await Promise.all([
        getRelationalPlanningReadModel(),
        prisma2.customerOrder.count({ where: { documentStatus: { notIn: ["CLOSED", "CANCELLED"] } } }),
        prisma2.productionPlanProposal.findMany({ select: { status: true } })
      ]);
      const requirements = readModel.requirements || [];
      const totalGrossDemandPieces = requirements.reduce((sum, r) => sum + Number(r.grossDemandQuantity || 0), 0);
      const totalNetProductionRequirementsPieces = requirements.reduce((sum, r) => sum + Number(r.netToProduceQuantity || 0), 0);
      const totalMaterialShortageKg = requirements.reduce((sum, r) => sum + Number(r.materialShortageKg || 0), 0);
      const activeSuggestionsCount = proposals.filter((p) => p.status === "DRAFT").length;
      const approvedPlansCount = proposals.filter((p) => p.status === "APPROVED" || p.status === "RELEASED").length;
      const criticalPartsRequiringImmediateAction = requirements.filter((r) => Number(r.netToProduceQuantity || 0) > 0 || r.hasMaterialShortage).map((r) => ({
        partCode: r.partCode,
        partName: r.partName,
        netShortage: Number(r.netToProduceQuantity || 0),
        dueDate: r.demandLines?.[0]?.dueDate || (/* @__PURE__ */ new Date()).toISOString(),
        hasMaterialShortage: Boolean(r.hasMaterialShortage)
      }));
      return res.json({
        success: true,
        source: "postgresql",
        data: {
          totalOpenOrdersCount: openOrdersCount,
          totalGrossDemandPieces,
          totalNetProductionRequirementsPieces,
          totalMaterialShortageKg,
          activeSuggestionsCount,
          approvedPlansCount,
          infeasiblePlansCount: 0,
          averageMachineCapacityUtilizationPercent: 0,
          criticalPartsRequiringImmediateAction
        }
      });
    }
    const metrics = getPlanningDashboardMetrics();
    res.json({ success: true, data: metrics });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error instanceof Error ? error.message : "\u062E\u0637\u0627 \u062F\u0631 \u0645\u062D\u0627\u0633\u0628\u0647 \u0645\u0639\u06CC\u0627\u0631\u0647\u0627\u06CC \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u0631\u06CC\u0632\u06CC \u062A\u0648\u0644\u06CC\u062F"
    });
  }
});
